#define E_BUDGET_NO_MAIN
#include "e_budget_relaxed_hnsw.cpp"

namespace {
using namespace vann;

class AuthSQ {
public:
 explicit AuthSQ(const HnswIndex&h):d_(h.dimension()),lo_(d_,INFINITY),span_(d_),code_(h.size()*d_){std::vector<float>hi(d_,-INFINITY);for(size_t id=0;id<h.size();++id)for(int j=0;j<d_;++j){lo_[j]=std::min(lo_[j],h.vector(id)[j]);hi[j]=std::max(hi[j],h.vector(id)[j]);}for(int j=0;j<d_;++j)span_[j]=hi[j]-lo_[j];for(size_t id=0;id<h.size();++id)for(int j=0;j<d_;++j){double u=span_[j]>0?(h.vector(id)[j]-lo_[j])/span_[j]:0;code_[id*d_+j]=uint8_t(std::clamp(int(std::floor(u*64)),0,63));}}
 std::vector<uint8_t>sq4(int id)const{return pack(id,4,true);}std::vector<uint8_t>delta(int id)const{return pack(id,2,false);}
private:
 std::vector<uint8_t>pack(int id,int bits,bool high)const{std::vector<uint8_t>out;uint32_t acc=0;int used=0;for(int j=0;j<d_;++j){uint8_t x=high?code_[size_t(id)*d_+j]>>2:code_[size_t(id)*d_+j]&3U;acc|=uint32_t(x)<<used;used+=bits;while(used>=8){out.push_back(uint8_t(acc));acc>>=8;used-=8;}}if(used)out.push_back(uint8_t(acc));return out;}
 int d_;std::vector<float>lo_,span_;std::vector<uint8_t>code_;
};

void domain(std::vector<uint8_t>&out,const std::string&s){out.insert(out.end(),s.begin(),s.end());}
Hash leaf_sq4(const AuthSQ&sq,int id){std::vector<uint8_t>b;domain(b,"record/sq4/v1");append_bytes(b,uint32_t(id));auto x=sq.sq4(id);b.insert(b.end(),x.begin(),x.end());return sha256(b.data(),b.size());}
Hash leaf_delta(const AuthSQ&sq,int id){std::vector<uint8_t>b;domain(b,"record/delta46/v1");append_bytes(b,uint32_t(id));auto x=sq.delta(id);b.insert(b.end(),x.begin(),x.end());return sha256(b.data(),b.size());}
Hash leaf_raw(const HnswIndex&h,int id){std::vector<uint8_t>b;domain(b,"record/raw/v1");append_bytes(b,uint32_t(id));const auto*p=reinterpret_cast<const uint8_t*>(h.vector(id));b.insert(b.end(),p,p+h.dimension()*sizeof(float));return sha256(b.data(),b.size());}
Hash neighbor_commitment(const AuthSQ&sq,const Hash&snapshot,int id){std::vector<uint8_t>b;domain(b,"snapshot/sq4/v1");append_hash(b,snapshot);append_bytes(b,uint32_t(id));auto x=sq.sq4(id);b.insert(b.end(),x.begin(),x.end());return sha256(b.data(),b.size());}
Hash leaf_adj(const HnswIndex&h,int id,int level){std::vector<uint8_t>b;domain(b,"record/adj/v1");append_bytes(b,uint32_t(id));append_bytes(b,uint32_t(level));auto ns=h.neighbors(id,level);append_bytes(b,uint32_t(ns.size()));for(int u:ns)append_bytes(b,uint32_t(u));return sha256(b.data(),b.size());}
Hash leaf_er(const HnswIndex&h,const AuthSQ&sq,const Hash&snapshot,int id,int level){std::vector<uint8_t>b;domain(b,"record/expansion/v1");append_bytes(b,uint32_t(id));append_bytes(b,uint32_t(level));auto ns=h.neighbors(id,level);append_bytes(b,uint32_t(ns.size()));for(int u:ns){append_bytes(b,uint32_t(u));append_hash(b,neighbor_commitment(sq,snapshot,u));}return sha256(b.data(),b.size());}
Hash leaf_er_direct(const HnswIndex&h,const AuthSQ&sq,const Hash&snapshot,int id,int level){std::vector<uint8_t>b;domain(b,"record/expansion-direct/v1");append_hash(b,snapshot);append_bytes(b,uint32_t(id));append_bytes(b,uint32_t(level));auto ns=h.neighbors(id,level);std::sort(ns.begin(),ns.end());append_bytes(b,uint32_t(ns.size()));for(int u:ns){append_bytes(b,uint32_t(u));auto x=sq.sq4(u);b.insert(b.end(),x.begin(),x.end());}return sha256(b.data(),b.size());}
Hash leaf_er_direct_cached(const HnswIndex&h,const std::unordered_map<int,std::vector<uint8_t>>&cache,const Hash&snapshot,int id,int level){std::vector<uint8_t>b;domain(b,"record/expansion-direct/v1");append_hash(b,snapshot);append_bytes(b,uint32_t(id));append_bytes(b,uint32_t(level));auto ns=h.neighbors(id,level);std::sort(ns.begin(),ns.end());append_bytes(b,uint32_t(ns.size()));for(int u:ns){append_bytes(b,uint32_t(u));const auto&x=cache.at(u);b.insert(b.end(),x.begin(),x.end());}return sha256(b.data(),b.size());}
std::vector<int>unique(std::vector<int>x){std::sort(x.begin(),x.end());x.erase(std::unique(x.begin(),x.end()),x.end());return x;}

struct Agg{double hits=0,expanded=0,disclosed=0,route_targets=0,ref_targets=0,leaves=0,siblings=0,proof=0,route_siblings=0,route_proof=0,commitments=0,sq4=0,delta=0,raw=0,adj=0,meta=0,total=0,neighbor_refs=0,unique_neighbors=0;};
}

#ifndef EXPANSION_CENTRIC_NO_MAIN
int main()try{using namespace vann;Config c;c.queries=100;Matrix base=read_fvecs(c.dataset+"/sift_base.fvecs",c.base),queries=read_fvecs(c.dataset+"/sift_query.fvecs",c.queries);HnswIndex h=build_hnsw(base,c.M,c.efc,c.cache);base.values.clear();base.values.shrink_to_fit();ESQ route_sq(h);AuthSQ auth_sq(h);auto gt=ground_truth(h,queries,c.k);
 std::vector<size_t>adj_base(h.size()+1);for(size_t id=0;id<h.size();++id)adj_base[id+1]=adj_base[id]+h.index->hnsw.levels[id];size_t n=h.size(),na=adj_base.back();const std::string sid="sift100k-static-snapshot-v1";Hash snapshot=sha256(sid.data(),sid.size());std::vector<Hash>record_leaves(n+na+2*n),er_leaves(na+2*n),direct_leaves(na+2*n);std::cerr<<"Building three real Merkle trees...\n";for(size_t id=0;id<n;++id){record_leaves[id]=leaf_sq4(auth_sq,id);record_leaves[n+na+id]=leaf_delta(auth_sq,id);record_leaves[n+na+n+id]=leaf_raw(h,id);er_leaves[na+id]=direct_leaves[na+id]=record_leaves[n+na+id];er_leaves[na+n+id]=direct_leaves[na+n+id]=record_leaves[n+na+n+id];for(int l=0;l<h.index->hnsw.levels[id];++l){size_t p=adj_base[id]+l;record_leaves[n+p]=leaf_adj(h,id,l);er_leaves[p]=leaf_er(h,auth_sq,snapshot,id,l);direct_leaves[p]=leaf_er_direct(h,auth_sq,snapshot,id,l);}}
 MerkleTree record_tree(std::move(record_leaves)),er_tree(std::move(er_leaves)),direct_tree(std::move(direct_leaves));Agg a,b,d;std::ofstream per("expansion_centric_merkle_per_query.csv");per<<"query,recall,expanded,disclosed,opened_adjacencies,neighbor_refs,unique_neighbor_ids,duplicate_commitment_ratio,record_route_targets,record_refinement_targets,record_sibling_hashes,record_proof_bytes,er_route_targets,er_refinement_targets,er_sibling_hashes,er_proof_bytes,added_commitment_bytes,direct_sibling_hashes,direct_proof_bytes,direct_added_commitment_bytes\n";
 for(int qi=0;qi<c.queries;++qi){ETrace t=run_e(h,route_sq,queries.row(qi),c.k,64,"sq4");std::unordered_set<int>answer(t.answer.begin(),t.answer.end());double hits=0;for(int id:gt[qi])hits+=answer.count(id);std::unordered_map<int,std::vector<uint8_t>>sq4_cache;std::vector<int>record_route,er_route,record_all,er_all;for(int id:t.disclosed){record_route.push_back(id);sq4_cache.emplace(id,auth_sq.sq4(id));}std::unordered_set<int>neighbor_ids;double refs=0;for(auto x:t.opened){size_t p=adj_base[x.local_id]+x.level;record_route.push_back(int(n+p));er_route.push_back(int(p));auto ns=h.neighbors(x.local_id,x.level);refs+=ns.size();neighbor_ids.insert(ns.begin(),ns.end());if(leaf_er_direct_cached(h,sq4_cache,snapshot,x.local_id,x.level)!=direct_tree.leaf(p))throw std::runtime_error("direct ER cannot be reconstructed from disclosed SQ4 cache");}record_route=unique(std::move(record_route));er_route=unique(std::move(er_route));record_all=record_route;er_all=er_route;for(int id:t.refined){record_all.push_back(int(n+na+id));er_all.push_back(int(na+id));}for(int id:t.raw){record_all.push_back(int(n+na+n+id));er_all.push_back(int(na+n+id));}record_all=unique(std::move(record_all));er_all=unique(std::move(er_all));MerkleProof rp=record_tree.prove(record_all),ep=er_tree.prove(er_all),dp=direct_tree.prove(er_all),rrp=record_tree.prove(record_route),erp=er_tree.prove(er_route),drp=direct_tree.prove(er_route);verify_merkle_selection(record_tree,record_all,rp);verify_merkle_selection(er_tree,er_all,ep);verify_merkle_selection(direct_tree,er_all,dp);verify_merkle_selection(record_tree,record_route,rrp);verify_merkle_selection(er_tree,er_route,erp);verify_merkle_selection(direct_tree,er_route,drp);double common=t.sq4+t.delta+t.raw_bytes+t.adjacency+t.metadata,commit=refs*32.0,ref_targets=t.refined.size()+t.raw.size();auto add=[&](Agg&z,const std::vector<int>&route,const std::vector<int>&all,const MerkleProof&p,const MerkleProof&pr,double added){z.hits+=hits;z.expanded+=t.expanded.size();z.disclosed+=t.disclosed.size();z.route_targets+=route.size();z.ref_targets+=ref_targets;z.leaves+=all.size();z.siblings+=p.nodes.size();z.proof+=p.bytes();z.route_siblings+=pr.nodes.size();z.route_proof+=pr.bytes();z.commitments+=added;z.sq4+=t.sq4;z.delta+=t.delta;z.raw+=t.raw_bytes;z.adj+=t.adjacency;z.meta+=t.metadata;z.total+=common+p.bytes()+added;z.neighbor_refs+=refs;z.unique_neighbors+=neighbor_ids.size();};add(a,record_route,record_all,rp,rrp,0);add(b,er_route,er_all,ep,erp,commit);add(d,er_route,er_all,dp,drp,0);per<<qi<<','<<hits/c.k<<','<<t.expanded.size()<<','<<t.disclosed.size()<<','<<t.opened.size()<<','<<refs<<','<<neighbor_ids.size()<<','<<(refs?1.0-neighbor_ids.size()/refs:0)<<','<<record_route.size()<<','<<ref_targets<<','<<rp.nodes.size()<<','<<rp.bytes()<<','<<er_route.size()<<','<<ref_targets<<','<<ep.nodes.size()<<','<<ep.bytes()<<','<<commit<<','<<dp.nodes.size()<<','<<dp.bytes()<<",0\n";}
 std::ofstream out("expansion_centric_merkle_q100.csv");out<<"method,recall_at_10,avg_expanded,avg_disclosed,routing_leaf_targets,refinement_leaf_targets,unique_authenticated_leaves,multiproof_sibling_hashes,merkle_proof_kib,routing_sibling_hashes,routing_proof_kib,added_neighbor_commitment_kib,sq4_payload_kib,delta_payload_kib,raw_payload_kib,adjacency_id_payload_kib,metadata_kib,total_authentication_vo_kib,total_vo_kib,avg_neighbor_refs,avg_unique_neighbor_ids,duplicate_commitment_ratio\n";auto emit=[&](const std::string&name,const Agg&z){double q=c.queries;out<<name<<','<<z.hits/(q*c.k)<<','<<z.expanded/q<<','<<z.disclosed/q<<','<<z.route_targets/q<<','<<z.ref_targets/q<<','<<z.leaves/q<<','<<z.siblings/q<<','<<z.proof/q/1024<<','<<z.route_siblings/q<<','<<z.route_proof/q/1024<<','<<z.commitments/q/1024<<','<<z.sq4/q/1024<<','<<z.delta/q/1024<<','<<z.raw/q/1024<<','<<z.adj/q/1024<<','<<z.meta/q/1024<<','<<(z.proof+z.commitments)/q/1024<<','<<z.total/q/1024<<','<<z.neighbor_refs/q<<','<<z.unique_neighbors/q<<','<<(1-z.unique_neighbors/z.neighbor_refs)<<'\n';};emit("Record-wise-Merkle",a);emit("Previous-Expansion-Centric",b);emit("Direct-Content-Expansion-Centric",d);std::cout<<std::fixed<<std::setprecision(4)<<"Record-wise proof="<<a.proof/c.queries/1024<<" KiB auth="<<(a.proof+a.commitments)/c.queries/1024<<" KiB total="<<a.total/c.queries/1024<<" KiB\nPrevious ER proof="<<b.proof/c.queries/1024<<" KiB commitments="<<b.commitments/c.queries/1024<<" KiB total="<<b.total/c.queries/1024<<" KiB\nDirect ER proof="<<d.proof/c.queries/1024<<" KiB commitments="<<d.commitments/c.queries/1024<<" KiB total="<<d.total/c.queries/1024<<" KiB\n";return 0;}catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<'\n';return 1;}
#endif
